typedef struct node {
    int value;
    struct node *next;
} Node;

bool push_front(Node **head, int value) {
    Node *n = malloc(sizeof *n);
    if (n == NULL) {
        return false;
    }
    n->value = value;
    n->next = *head;
    *head = n;
    return true;
}

Node *find(Node *head, int value) {
    for (Node *p = head; p != NULL; p = p->next) {
        if (p->value == value) {
            return p;
        }
    }
    return NULL;
}

bool remove_first(Node **head, int value) {
    Node **link = head;
    while (*link != NULL && (*link)->value != value) {
        link = &(*link)->next;
    }
    if (*link == NULL) {
        return false;
    }
    Node *dead = *link;
    *link = dead->next;
    free(dead);
    return true;
}

void free_list(Node **head) {
    Node *p = *head;
    while (p != NULL) {
        Node *next = p->next;
        free(p);
        p = next;
    }
    *head = NULL;
}

