bool enqueue(Queue *q, int value) {
    Node *n = malloc(sizeof *n);
    if (n == NULL) {
        return false;
    }
    n->value = value;
    n->next = NULL;
    if (q->tail == NULL) {
        q->head = n;
        q->tail = n;
    } else {
        q->tail->next = n;
    }
    return true;
}

bool dequeue(Queue *q, int *out) {
    if (q->head == NULL) {
        return false;
    }
    Node *dead = q->head;
    *out = dead->value;
    q->head = dead->next;
    if (q->head == NULL) {
        q->tail = NULL;
    }
    free(dead);
    return true;
}

